import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"加法器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/modules/add/index.md","filePath":"v0.4.0-alpha/modules/add/index.md"}'),r={name:"v0.4.0-alpha/modules/add/index.md"};function i(n,t,l,c,h,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="加法器" tabindex="-1">加法器 <a class="header-anchor" href="#加法器" aria-label="Permalink to &quot;加法器&quot;">​</a></h1><p>适用：v0.4.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>add</code> · 模块定义版本：5</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>把各输入流同一 item、同一分量的数值相加。它适合叠加信号与噪声、合成多频信号，也能对向量逐分量求和。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>信号源 1.out → 加法器.in1</code>，<code>信号源 2.out → 加法器.in2</code>；需要更多输入时先调整输入路数，再连接新增流端口。所有已声明的流输入都需要接线。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in1</code>（输入 1）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输入</td><td><code>in2</code>（输入 2）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>各路的元素类型、向量长度和采样率必须匹配。向量相加不会把分量串成更长的流：两个长度相同的 item 相加后，输出仍保持原长度。</p><p>选择整数类型时保留整数运算语义，不能按浮点结果解释。先用容易计算的小数值检查接线，再加入较大信号或更多分支。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>输入路数<br><code>num_inputs</code></td><td><code>2</code></td><td>范围 1 至 1024；当前画布支持 1–1024 路。修改后须重新准备，缩减前请先解除相关连线和工具绑定。</td><td>重新准备</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr><tr><td>元素类型<br><code>element_type</code></td><td><code>numeric_f64</code></td><td>实数 float32 (<code>numeric_f64</code>)；有符号 int16 (<code>int16</code>)；有符号 int32 (<code>int32</code>)</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>输入路数、元素类型和向量长度决定运行结构，修改后重新准备。缩减路数前先解除被删除端口的连线和相关绑定；修改草稿不会重接当前任务。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.4.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><p>实数处理示例中的加法器汇合 64 Hz、768 Hz 与噪声三路。观察输出波形，再绑定其频谱输出，识别两条主频率分量。低通、高通、带通都从这个相同的混合输出取数，便于公平对比。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>只接一路为什么不能准备？</strong> 查看输入路数，未使用的已声明输入也要接线，或减少路数后重新准备。</p><p><strong>不同速率的信号能直接相加吗？</strong> 不能。先通过合适的抽取或插值使实际 item 速率一致。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/04-signal-views/">04 时域、频谱与瀑布</a></li><li><a href="./../../learn/05-noise/">05 信号混入噪声</a></li><li><a href="./../../learn/06-filter/">06 滤波保留了什么</a></li></ul>',28)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
